CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin')), xp INTEGER NOT NULL DEFAULT 0 CHECK(xp >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (token TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_sessions_user_expires ON sessions(user_id, expires_at);
CREATE TABLE subjects (id BIGSERIAL PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', icon TEXT NOT NULL DEFAULT 'dna');
CREATE TABLE topics (id BIGSERIAL PRIMARY KEY, subject_id BIGINT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, parent_id BIGINT REFERENCES topics(id) ON DELETE CASCADE, slug TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', theory TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'topic' CHECK(kind IN ('section','topic','subtopic','lesson')), published BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(subject_id,slug));
CREATE INDEX idx_topics_parent_position ON topics(parent_id,position);
CREATE TABLE questions (id BIGSERIAL PRIMARY KEY, topic_id BIGINT NOT NULL REFERENCES topics(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('single','multiple','matching','sequence','text')), prompt TEXT NOT NULL, instruction TEXT NOT NULL DEFAULT '', explanation TEXT NOT NULL, difficulty INTEGER NOT NULL DEFAULT 1 CHECK(difficulty BETWEEN 1 AND 3), answer_json TEXT NOT NULL, content_json TEXT NOT NULL DEFAULT '{}', media_json TEXT NOT NULL DEFAULT '[]', tags_json TEXT NOT NULL DEFAULT '[]', source TEXT NOT NULL DEFAULT '', exam_line INTEGER, points INTEGER NOT NULL DEFAULT 1, estimated_seconds INTEGER NOT NULL DEFAULT 90, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_questions_topic ON questions(topic_id,active);
CREATE TABLE question_options (id BIGSERIAL PRIMARY KEY, question_id BIGINT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, value TEXT NOT NULL, label TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE attempts (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id BIGINT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, answer_json TEXT NOT NULL, correct BOOLEAN NOT NULL, duration_seconds INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, next_review_at TIMESTAMPTZ, interval_days INTEGER NOT NULL DEFAULT 0, review_stage INTEGER NOT NULL DEFAULT 0, result_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX idx_attempts_user_question ON attempts(user_id,question_id); CREATE INDEX idx_attempts_user_created ON attempts(user_id,created_at DESC); CREATE INDEX idx_attempts_due ON attempts(user_id,next_review_at);
CREATE TABLE topic_progress (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, topic_id BIGINT NOT NULL REFERENCES topics(id) ON DELETE CASCADE, mastery INTEGER NOT NULL DEFAULT 0 CHECK(mastery BETWEEN 0 AND 100), updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,topic_id));
CREATE TABLE activity_days (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day DATE NOT NULL, solved INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,day));
CREATE TABLE skills (id BIGSERIAL PRIMARY KEY, subject_id BIGINT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, slug TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL DEFAULT 0, UNIQUE(subject_id,slug));
CREATE TABLE question_skills (question_id BIGINT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, skill_id BIGINT NOT NULL REFERENCES skills(id) ON DELETE CASCADE, weight DOUBLE PRECISION NOT NULL DEFAULT 1 CHECK(weight > 0), PRIMARY KEY(question_id,skill_id));
CREATE TABLE lesson_progress (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, lesson_id BIGINT NOT NULL REFERENCES topics(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'not_started' CHECK(status IN ('not_started','in_progress','completed')), theory_read BOOLEAN NOT NULL DEFAULT FALSE, questions_solved INTEGER NOT NULL DEFAULT 0, correct_answers INTEGER NOT NULL DEFAULT 0, last_activity_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, PRIMARY KEY(user_id,lesson_id));
CREATE TABLE training_sessions (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, topic_id BIGINT REFERENCES topics(id) ON DELETE SET NULL, mode TEXT NOT NULL DEFAULT 'adaptive' CHECK(mode IN ('adaptive','new','review','mistakes','topic')), target_questions INTEGER NOT NULL DEFAULT 10 CHECK(target_questions BETWEEN 1 AND 100), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','abandoned')), correct_count INTEGER NOT NULL DEFAULT 0, answered_count INTEGER NOT NULL DEFAULT 0, started_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TIMESTAMPTZ);
CREATE TABLE training_session_questions (session_id BIGINT NOT NULL REFERENCES training_sessions(id) ON DELETE CASCADE, question_id BIGINT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, position INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','answered','skipped')), attempt_id BIGINT REFERENCES attempts(id) ON DELETE SET NULL, presented_at TIMESTAMPTZ, answered_at TIMESTAMPTZ, PRIMARY KEY(session_id,position), UNIQUE(session_id,question_id));
CREATE INDEX idx_training_sessions_user_status ON training_sessions(user_id,status,started_at DESC); CREATE INDEX idx_training_questions_next ON training_session_questions(session_id,state,position);
CREATE TABLE mock_exams (id BIGSERIAL PRIMARY KEY, subject_id BIGINT NOT NULL REFERENCES subjects(id), title TEXT NOT NULL, duration_minutes INTEGER NOT NULL DEFAULT 210, published BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE mock_exam_questions (mock_exam_id BIGINT NOT NULL REFERENCES mock_exams(id) ON DELETE CASCADE, question_id BIGINT NOT NULL REFERENCES questions(id), position INTEGER NOT NULL, PRIMARY KEY(mock_exam_id,question_id));
CREATE TABLE mock_exam_attempts (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), mock_exam_id BIGINT NOT NULL REFERENCES mock_exams(id), started_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TIMESTAMPTZ, score INTEGER, answers_json TEXT NOT NULL DEFAULT '{}');
